class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& pts) {
        int n = pts.size();
        vector<array<int,3>> edges;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                edges.push_back({abs(pts[i][0]-pts[j][0]) + abs(pts[i][1]-pts[j][1]), i, j});
        sort(edges.begin(), edges.end());
        DSU dsu(n); int cost = 0, used = 0;
        for (auto& [w, u, v] : edges) {
            if (dsu.uni(u, v)) { cost += w; if (++used == n - 1) break; }
        }
        return cost;
    }
};

class Solution:
    def minCostConnectPoints(self, pts: list[list[int]]) -> int:
        n = len(pts)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]; x = parent[x]
            return x
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                w = abs(pts[i][0]-pts[j][0]) + abs(pts[i][1]-pts[j][1])
                edges.append((w, i, j))
        edges.sort()
        cost = used = 0
        for w, u, v in edges:
            ru, rv = find(u), find(v)
            if ru != rv:
                parent[ru] = rv; cost += w; used += 1
                if used == n - 1:
                    break
        return cost

