class Solution {
    int build(int n, vector<vector<int>>& e, int skip, int force) {
        DSU dsu(n); int w = 0;
        if (force >= 0) { dsu.uni(e[force][0], e[force][1]); w += e[force][2]; }
        for (int i = 0; i < (int)e.size(); i++) {
            if (i == skip) continue;
            if (dsu.uni(e[i][0], e[i][1])) w += e[i][2];
        }
        return dsu.cnt == 1 ? w : INT_MAX;
    }
